var ENT=[["TDD", "Test-driven development discipline."], ["TLA+", "Formal specification catching design bugs."], ["Testcontainers", "Real dependencies in Docker for tests."], ["Pact", "Consumer-driven contract testing."], ["pytest", "Python's expressive test framework with fixtures and 1000-plus plugins."], ["Jest", "Meta's batteries-included JavaScript test runner with snapshots."], ["JUnit", "The Java xUnit framework that started the testing-framework lineage."]];
var TECH=[["Unit testing", "Isolating the smallest units with fast deterministic tests."], ["Integration testing", "Verifying components collaborate correctly across boundaries."], ["Property-based testing", "Asserting invariants over generated inputs instead of hand cases."], ["Fuzzing", "Feeding random and mutated inputs hunting for crashes."], ["Mutation testing", "Seeding bugs to check the suite actually catches them."], ["Test doubles", "Mocks, stubs and fakes isolating units from slow dependencies."], ["Snapshot testing", "Locking rendered output against accidental change."], ["Contract testing", "Consumer-driven pacts keeping services compatible."], ["Load testing", "Proving performance under expected and spike traffic."], ["Formal verification", "Mathematically proving critical properties of designs."]];
var STDN=["xUnit architecture", "ISTQB syllabus", "TDD cycle"];
